function getKillBalls(ctx) {
  var TH = ctx.params.missThreshold != null ? ctx.params.missThreshold : 12;
  var miss = ctx.getMissValues(30);
  var best = null;
  for (var i = 0; i < miss.length; i++) {
    if (miss[i].value < TH) continue;
    if (best === null || miss[i].value > best.value ||
        (miss[i].value === best.value && miss[i].ball < best.ball)) best = miss[i];
  }
  return best === null ? [] : [best.ball];
}

function getKillBalls(ctx) {
  var TH = ctx.params.missThreshold != null ? ctx.params.missThreshold : 16;
  var recs = ctx.getSamePeriodRecords(ctx.currentShortPeriodSuffix);
  var result = [];
  for (var b = 1; b <= 16; b++) {
    var miss = 0;
    for (var i = recs.length - 1; i >= 0; i--) {
      if (recs[i].blueBall === b) break;
      miss++;
    }
    if (miss >= TH) result.push(b);
  }
  return result;
}

function getKillBalls(ctx) {
  var history = ctx.history(2);
  if (!history || history.length < 2) return [];
  var previousSet = {};
  var previous = history[0].redBalls;
  var latest = history[1].redBalls;
  for (var i = 0; i < previous.length; i++) previousSet[previous[i]] = true;
  var result = [];
  for (var j = 0; j < latest.length; j++) {
    if (previousSet[latest[j]]) result.push(latest[j]);
  }
  return result;
}

function getKillBalls(ctx) {
  var history = ctx.history(2);
  if (!history || history.length < 2) return [];
  var previousSet = {};
  var latestSet = {};
  var previous = history[0].redBalls;
  var latest = history[1].redBalls;
  for (var i = 0; i < previous.length; i++) previousSet[previous[i]] = true;
  for (var j = 0; j < latest.length; j++) latestSet[latest[j]] = true;
  var killed = {};
  for (var k = 0; k < latest.length; k++) {
    var anchor = latest[k];
    if (!previousSet[anchor]) continue;
    var left = anchor - 1;
    var right = anchor + 1;
    if (left >= 1 && latestSet[left]) { killed[anchor] = true; killed[left] = true; }
    if (right <= 33 && latestSet[right]) { killed[anchor] = true; killed[right] = true; }
  }
  var result = [];
  for (var key in killed) result.push(parseInt(key, 10));
  result.sort(function(a, b) { return a - b; });
  return result;
}

