function getKillBalls(ctx) {
  var latest = ctx.latestRecord;
  if (!latest) return [];
  function has(record, ball) {
    var reds = record.redBalls;
    for (var i = 0; i < reds.length; i++) if (reds[i] === ball) return true;
    return false;
  }
  var killed = {};
  for (var i = 0; i < latest.redBalls.length; i++) {
    var a = latest.redBalls[i];
    for (var delta = -1; delta <= 1; delta += 2) {
      var b = a + delta;
      if (b < 1 || b > 33 || has(latest, b)) continue;
      var miss = ctx.getMiss(b, 10000);
      if (miss < 1) continue;
      var segment = ctx.history(miss + 2);
      if (segment.length !== miss + 2) continue;
      if (!has(segment[1], b) || has(segment[1], a) ||
          !has(segment[0], a) || has(segment[0], b)) continue;
      var blocked = false;
      for (var j = 2; j < segment.length - 1; j++) {
        if (has(segment[j], a)) { blocked = true; break; }
      }
      if (!blocked) killed[b] = true;
    }
  }
  var result = [];
  for (var key in killed) result.push(parseInt(key, 10));
  result.sort(function(a, b) { return a - b; });
  return result;
}

function getKillBalls(ctx) {
  if (!ctx.latestRecord) return [];
  var reds = ctx.latestRecord.redBalls;
  var opened = {};
  var killed = {};
  for (var i = 0; i < reds.length; i++) opened[reds[i]] = true;
  for (var j = 0; j < reds.length; j++) {
    var start = reds[j];
    if (opened[start + 1] && opened[start + 2]) {
      killed[start] = true;
      killed[start + 1] = true;
      killed[start + 2] = true;
    }
  }
  var result = [];
  for (var key in killed) result.push(parseInt(key, 10));
  result.sort(function(a, b) { return a - b; });
  return result;
}

function getKillBalls(ctx) {
  var history = ctx.history(3);
  if (!history || history.length < 3) return [];
  var first = history[0].redBalls;
  var secondSet = {};
  var thirdSet = {};
  var second = history[1].redBalls;
  var third = history[2].redBalls;
  for (var i = 0; i < second.length; i++) secondSet[second[i]] = true;
  for (var j = 0; j < third.length; j++) thirdSet[third[j]] = true;
  var killed = {};
  for (var k = 0; k < first.length; k++) {
    var start = first[k];
    for (var delta = -1; delta <= 1; delta += 2) {
      var target = start + 3 * delta;
      if (target >= 1 && target <= 33 &&
          secondSet[start + delta] && thirdSet[start + 2 * delta]) killed[target] = true;
    }
  }
  var result = [];
  for (var key in killed) result.push(parseInt(key, 10));
  result.sort(function(a, b) { return a - b; });
  return result;
}

function getKillBalls(ctx) {
  if (!ctx.latestRecord) return [];
  var reds = ctx.latestRecord.redBalls;
  var opened = {};
  var killed = {};
  for (var i = 0; i < reds.length; i++) opened[reds[i]] = true;
  for (var j = 0; j < reds.length; j++) {
    var left = reds[j];
    var right = left + 1;
    if (!opened[right]) continue;
    var leftDistance = ctx.getPreviousRedOccurrenceDistance(left);
    var rightDistance = ctx.getPreviousRedOccurrenceDistance(right);
    if (leftDistance >= 2 && leftDistance === rightDistance) {
      killed[left] = true;
      killed[right] = true;
    }
  }
  var result = [];
  for (var key in killed) result.push(parseInt(key, 10));
  result.sort(function(a, b) { return a - b; });
  return result;
}
